{"file_path":"src/errors.js","content":"/**
 * The error type the CLI raises for every rejected input. `code` is the
 * process exit code the message belongs to (2 for ordinary failures, 3 for a
 * cycle), and `message` is the text written after `error: ` on standard
 * error.
 */
export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}
"}

