{"file_path":"src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph text format into a task table (name -> cost) and a
 * dependency table (name -> set of dependency names). Throws a `CliError`
 * with exit code 2 for any malformed line or unknown task reference. Does
 * not check for cycles; that is the caller's job once the graph is built.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depEntries = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNumber}: expected task <name> <cost>`, 2)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNumber}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNumber}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNumber}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNumber}: expected dep <name> <dependency>...`, 2)
      }
      const source = words[1]
      const dependencies = words.slice(2)
      if (!NAME_RE.test(source)) {
        throw new CliError(`line ${lineNumber}: invalid task name ${source}`, 2)
      }
      for (const dependency of dependencies) {
        if (!NAME_RE.test(dependency)) {
          throw new CliError(`line ${lineNumber}: invalid task name ${dependency}`, 2)
        }
      }
      depEntries.push({ source, dependencies })
    } else {
      throw new CliError(`line ${lineNumber}: unknown directive ${directive}`, 2)
    }
  }

  const deps = new Map()
  for (const name of tasks.keys()) deps.set(name, new Set())

  for (const entry of depEntries) {
    if (!tasks.has(entry.source)) throw new CliError(`unknown task ${entry.source}`, 2)
    for (const dependency of entry.dependencies) {
      if (!tasks.has(dependency)) throw new CliError(`unknown task ${dependency}`, 2)
    }
    for (const dependency of entry.dependencies) {
      deps.get(entry.source).add(dependency)
    }
  }

  return { tasks, deps }
}
"}

