{"file_path":"src/graph.js","content":"import { CliError } from './errors.js'

/**
 * Finds the first cycle a depth-first search discovers when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order, returning the list of names from the re-entered
 * task through the search stack back to a repeat of that name. Returns
 * `null` when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  function visit(node) {
    visited.add(node)
    onStack.add(node)
    stack.push(node)

    const neighbours = [...deps.get(node)].sort()
    for (const neighbour of neighbours) {
      if (onStack.has(neighbour)) {
        const start = stack.indexOf(neighbour)
        return [...stack.slice(start), neighbour]
      }
      if (!visited.has(neighbour)) {
        const cycle = visit(neighbour)
        if (cycle) return cycle
      }
    }

    stack.pop()
    onStack.delete(node)
    return null
  }

  for (const name of names) {
    if (visited.has(name)) continue
    const cycle = visit(name)
    if (cycle) return cycle
  }
  return null
}

/**
 * Raises the cycle as a `CliError` with exit code 3, formatted as the
 * specification requires, when the graph contains one.
 */
export function rejectCycle(tasks, deps) {
  const cycle = findCycle(tasks, deps)
  if (cycle) throw new CliError(`cycle: ${cycle.join(' -> ')}`, 3)
}

/**
 * Computes, for every task, the wave it sits in (depth), its start time and
 * its finish time, per the unlimited-worker schedule. A task's depth is 0
 * when it has no dependency and otherwise one more than the deepest
 * dependency's depth; its start is the greatest finish among its
 * dependencies, or 0 when it has none.
 */
export function computeTimings(tasks, deps) {
  const timings = new Map()

  function compute(name) {
    if (timings.has(name)) return timings.get(name)
    const dependencies = [...deps.get(name)]
    let depth = 0
    let start = 0
    for (const dependency of dependencies) {
      const dependencyTimings = compute(dependency)
      depth = Math.max(depth, dependencyTimings.depth + 1)
      start = Math.max(start, dependencyTimings.finish)
    }
    const finish = start + tasks.get(name)
    const result = { depth, start, finish }
    timings.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return timings
}

/**
 * Computes, for every task, the priority `pack` schedules by: the cost of
 * the longest chain of dependents starting at that task, counting its own
 * cost and then the costs down to a task nothing depends on.
 */
export function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, dependencySet] of deps) {
    for (const dependency of dependencySet) {
      dependents.get(dependency).push(name)
    }
  }

  const priorities = new Map()

  function compute(name) {
    if (priorities.has(name)) return priorities.get(name)
    let downstream = 0
    for (const dependent of dependents.get(name)) {
      downstream = Math.max(downstream, compute(dependent))
    }
    const priority = tasks.get(name) + downstream
    priorities.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) compute(name)
  return priorities
}
"}

