    }
    const finish = start + tasks.get(name)
    const result = { depth, start, finish }
    timings.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return timings
}

/**
 * Computes, for every task, the priority `pack` schedules by: the cost of
 * the longest chain of dependents starting at that task, counting its own
 * cost and then the costs down to a task nothing depends on.
 */
export function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, dependencySet] of deps) {
    for (const dependency of dependencySet) {
      dependents.get(dependency).push(name)
    }
  }

  const priorities = new Map()

  function compute(name) {
    if (priorities.has(name)) return priorities.get(name)
    let downstream = 0
    for (const dependent of dependents.get(name)) {
      downstream = Math.max(downstream, compute(dependent))
    }
    const priority = tasks.get(name) + downstream
    priorities.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) compute(name)
  return priorities
}
"}

