/**
 * Simulates the build graph on `workerCount` workers, greedily starting the
 * highest-priority ready task (ties broken by ascending name) on the
 * lowest-index free worker whenever both are available at the current
 * instant, and otherwise advancing time to the next worker becoming free.
 * Returns the per-worker run lists in start order and the makespan.
 */
export function packSchedule(tasks, deps, workerCount) {
  const priorities = computePriorities(tasks, deps)
  const names = [...tasks.keys()]
  const finish = new Map()
  const remaining = new Set(names)
  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, runs: [] }))

  let time = 0
  while (remaining.size > 0) {
    for (;;) {
      const freeWorker = workers.find((w) => w.busyUntil <= time)
      if (!freeWorker) break

      let best = null
      for (const name of remaining) {
        const ready = [...deps.get(name)].every((dependency) => finish.get(dependency) <= time)
        if (!ready) continue
        if (
          best === null ||
          priorities.get(name) > priorities.get(best) ||
          (priorities.get(name) === priorities.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const start = time
      const end = start + tasks.get(best)
      finish.set(best, end)
      freeWorker.busyUntil = end
      freeWorker.runs.push({ name: best, start, finish: end })
      remaining.delete(best)
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (const worker of workers) {
      if (worker.busyUntil > time) next = Math.min(next, worker.busyUntil)
    }
    time = next
  }

  const makespan = names.length === 0 ? 0 : Math.max(...[...finish.values()])
  return { workers, makespan }
}
"}

