{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { computeTimings, rejectCycle } from './graph.js'
import { packSchedule } from './schedule.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0], workers: null }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function runWaves(tasks, timings) {
  let output = ''
  if (tasks.size > 0) {
    const maxDepth = Math.max(...[...timings.values()].map((t) => t.depth))
    for (let depth = 0; depth <= maxDepth; depth++) {
      const names = [...tasks.keys()].filter((name) => timings.get(name).depth === depth).sort()
      output += `wave ${depth}: ${names.join(' ')}\n`
    }
  }
  const total = tasks.size === 0 ? 0 : Math.max(...[...timings.values()].map((t) => t.finish))
  output += `total ${total}\n`
  return output
}

function runExplain(tasks, timings) {
  let output = ''
  for (const name of [...tasks.keys()].sort()) {
    const { start, finish, depth } = timings.get(name)
    output += `${name} start=${start} finish=${finish} depth=${depth}\n`
  }
  const total = tasks.size === 0 ? 0 : Math.max(...[...timings.values()].map((t) => t.finish))
  output += `total ${total}\n`
  return output
}

function runPack(tasks, deps, workerCount) {
  const { workers, makespan } = packSchedule(tasks, deps, workerCount)
  let output = ''
  workers.forEach((worker, index) => {
    const runs = worker.runs.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join('')
    output += `worker ${index}:${runs}\n`
  })
  output += `makespan ${makespan}\n`
  return output
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const { tasks, deps } = parseGraph(input)
  rejectCycle(tasks, deps)

  if (args.mode === 'waves') {
    process.stdout.write(runWaves(tasks, computeTimings(tasks, deps)))
  } else if (args.mode === 'explain') {
    process.stdout.write(runExplain(tasks, computeTimings(tasks, deps)))
  } else {
    process.stdout.write(runPack(tasks, deps, args.workers))
  }
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.code)
  }
  throw err
}
"}

